/* Lot 100: the reader paint of names, hwb(), color-mix() and translucent colours (generated by scripts/lot100_colorgen.py; expectations from scripts/lot100_colormodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[4096];
static char g_o[1024];

static void prep(const char *css, int ms) {
    wf_site_set_time(ms);
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><p id=i>i</p></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    wf_site_set_time(0);
}

static const char *style_of(const char *id) {
    int i;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    return g_o;
}

static void test_l100_paint_0(void) {
    prep("#o { color: Orchid !important } #o { color: blue }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#da70d6\"", style_of("o"));
    prep("#o { color: hsl(30, 30.88%, 36.5949%) !important } #o { color: blue }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#7a5d41\"", style_of("o"));
    prep("#o { color: hsla(351.428 76.9 58.074); background-color: hwb(176 50% 71% /6%) }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#e64259;background-color:#6969690f\"", style_of("o"));
    prep("#o { color: hwb(170 50% 0%) }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#80ffea\"", style_of("o"));
    TEST_ASSERT_EQUAL_STRING("", style_of("i"));
    prep("#o { background-color: blue } #o { background-color: rgb(71%, 52%, 16) }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#b58510\"", style_of("o"));
    prep("#o { color: thistle !important } #o { color: blue }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#d8bfd8\"", style_of("o"));
}

